		return nil, nil
	}
	h := testHandlerWithTopo(t, ".", provider)

	get(t, h, "/api/topology")
	get(t, h, "/api/topology")
	if calls != 1 {
		t.Fatalf("provider calls after two GETs = %d, want 1", calls)
	}
	if rec := post(t, h, "/api/topology/refresh"); rec.Code != http.StatusOK {
		t.Fatalf("refresh status = %d, want 200", rec.Code)
	}
	if calls != 2 {
		t.Fatalf("provider calls after refresh = %d, want 2", calls)
	}
	get(t, h, "/api/topology")
	if calls != 2 {
		t.Fatalf("provider calls after post-refresh GET = %d, want 2", calls)
	}
}

// writeSystemHost writes a system-host scaffold declaring a system name, the
// record `sys create` leaves in the rendered host directory.
func writeSystemHost(t *testing.T, dir, name string) {
	t.Helper()
	intropyDir := filepath.Join(dir, ".intropy")
	if err := os.MkdirAll(intropyDir, 0o755); err != nil {
		t.Fatal(err)
	}
	body := `{"schemaVersion":1,"template":"system-host","owner":"integrio-intropy","repo":"intropy-templates","version":"v0.2.0","role":"system-host","values":{"name":"` + name + `"}}` + "\n"
	if err := os.WriteFile(filepath.Join(intropyDir, "scaffold.json"), []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

// TestIntegrationsSystemFromHost checks that components scaffolded as
// siblings of a system host — the layout `sys create` produces — are grouped
// under the host's declared system name, even directly under the workspace
// root where no folder-derived system exists.
func TestIntegrationsSystemFromHost(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeScaffold(t, filepath.Join(tmp, "order-extractor"), "extractor", "v0.2.0")
	writeScaffold(t, filepath.Join(tmp, "order-loader"), "loader", "v0.2.0")
	writeSystemHost(t, filepath.Join(tmp, "system-host"), "order-flow")

	rec := get(t, testHandler(t, "."), "/api/integrations")
	var entries []map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &entries); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	if len(entries) != 2 {
		t.Fatalf("entries = %d, want 2 (host filtered)", len(entries))
	}
	for _, e := range entries {
		if e["system"] != "order-flow" {
			t.Errorf("system for %v = %v, want order-flow", e["name"], e["system"])
		}
		if _, present := e["domain"]; present {
			t.Errorf("domain for %v = %v, want absent at workspace root", e["name"], e["domain"])
		}
		// The workspace root is the system directory, and "." is what the
		// host's topology record carries as its path.
		if e["systemPath"] != "." {
			t.Errorf("systemPath for %v = %v, want .", e["name"], e["systemPath"])
		}
	}
}

// TestIntegrationsSystemFromHostNested checks that a declared system name
// overrides the folder-derived one, and the domain remains folder-derived.
func TestIntegrationsSystemFromHostNested(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeScaffold(t, filepath.Join(tmp, "sales", "erp", "order-intake"), "extractor", "v0.2.0")
	writeSystemHost(t, filepath.Join(tmp, "sales", "erp", "system-host"), "erp-sync")

	rec := get(t, testHandler(t, "."), "/api/integrations")
	var entries []map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &entries); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	if len(entries) != 1 {
		t.Fatalf("entries = %d, want 1", len(entries))
	}
	if entries[0]["system"] != "erp-sync" || entries[0]["domain"] != "sales" {
		t.Errorf("coords = %v/%v, want erp-sync/sales", entries[0]["system"], entries[0]["domain"])
	}
	if entries[0]["systemPath"] != "sales/erp" {
		t.Errorf("systemPath = %v, want sales/erp", entries[0]["systemPath"])
	}
}

// TestIntegrationsSystemPathDistinct pins the repo-root regression: two
// system directories whose hosts declare the same system name (e.g. one
// copied from the other) must keep distinct systemPath keys, or every
// consumer that groups by name merges them and can no longer match either
// group to its declared topology.
func TestIntegrationsSystemPathDistinct(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	for _, sys := range []string{"fulfillment", "order-flow"} {
		writeScaffold(t, filepath.Join(tmp, "orders", sys, "order-extractor"), "extractor", "v0.2.0")
		writeSystemHost(t, filepath.Join(tmp, "orders", sys, "host"), "order-flow")
	}

	rec := get(t, testHandler(t, "."), "/api/integrations")
	var entries []map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &entries); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	if len(entries) != 2 {
		t.Fatalf("entries = %d, want 2", len(entries))
	}
	paths := map[string]bool{}
	for _, e := range entries {
		if e["system"] != "order-flow" {
			t.Errorf("system for %v = %v, want the declared order-flow", e["path"], e["system"])
		}
		sp, _ := e["systemPath"].(string)
		paths[sp] = true
	}
	for _, want := range []string{"orders/fulfillment", "orders/order-flow"} {
		if !paths[want] {
			t.Errorf("systemPaths = %v, want both orders/fulfillment and orders/order-flow", paths)
		}
	}
}

// TestIntegrationsFilterSupportProjects checks that the system host and the
// shared contracts library are infrastructure, not catalog entries: they are
// absent from listings and their paths do not resolve to a detail view.
func TestIntegrationsFilterSupportProjects(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeScaffold(t, filepath.Join(tmp, "pim-extractor"), "extractor", "v0.1.6")
	writeScaffoldRole(t, filepath.Join(tmp, "orders-system-host"), "system-host", "v0.1.6", "system-host")
	writeScaffoldRole(t, filepath.Join(tmp, "orders-contracts"), "contracts", "v0.1.6", "shared-library")

	for _, path := range []string{"/api/integrations", "/api/flow"} {
		rec := get(t, testHandler(t, "."), path)
		var entries []map[string]any
		if err := json.Unmarshal(rec.Body.Bytes(), &entries); err != nil {
			t.Fatalf("%s: body not JSON: %v\n%s", path, err, rec.Body.String())
		}
		if len(entries) != 1 || entries[0]["name"] != "pim-extractor" {
			t.Errorf("%s: entries = %v, want just pim-extractor", path, entries)
		}
	}

	if rec := get(t, testHandler(t, "."), "/api/integrations/orders-system-host"); rec.Code != http.StatusNotFound {
		t.Errorf("host detail status = %d, want 404", rec.Code)
	}
}

// TestIntegrationDetailRoot covers an integration scaffolded at the
// workspace root: its identifier is "." but a browser strips that segment,
// so /api/integrations/ (empty path) must resolve to the root integration.
func TestIntegrationDetailRoot(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeScaffold(t, tmp, "transactional", "v0.1.6")

	rec := get(t, testHandler(t, "."), "/api/integrations/")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200: %s", rec.Code, rec.Body.String())
	}
	var detail map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &detail); err != nil {
		t.Fatalf("body not JSON: %v", err)
	}
	if detail["path"] != "." || detail["template"] != "transactional" {
		t.Errorf("unexpected detail: %v", detail)
	}
}

func TestIntegrationDetailNotFound(t *testing.T) {
	t.Chdir(t.TempDir())
	rec := get(t, testHandler(t, "."), "/api/integrations/nope")
	if rec.Code != http.StatusNotFound {
		t.Fatalf("status = %d, want 404", rec.Code)
	}
}

func TestSPAFallback(t *testing.T) {
	h := testHandler(t, t.TempDir())
	for _, path := range []string{"/", "/some/deep/route"} {
		rec := get(t, h, path)
		if rec.Code != http.StatusOK {
			t.Errorf("%s: status = %d, want 200", path, rec.Code)
		}
		if ct := rec.Header().Get("Content-Type"); !strings.HasPrefix(ct, "text/html") {
			t.Errorf("%s: content-type = %q, want text/html", path, ct)
		}
		if !strings.Contains(rec.Body.String(), "Intropy Dashboard") {
			t.Errorf("%s: body is not index.html", path)
		}
	}
}

// A missing file must 404, not fall back to index.html. Answering a script
// request with HTML and a 200 fails the browser's MIME check and surfaces only
// as a blank page — the failure mode when a binary is built without `make web`.
func TestMissingAssetIsNotFound(t *testing.T) {
	// Names that cannot exist in either build state, so this holds whether or
	// not `make web` has run.
	h := testHandler(t, t.TempDir())
	for _, path := range []string{
		"/assets/index-nosuchbundle.js",
		"/assets/index-nosuchbundle.css",
		"/nested/deep/missing.js",
	} {
		rec := get(t, h, path)
		if rec.Code != http.StatusNotFound {
			t.Errorf("%s: status = %d, want 404 (body: %.40q)", path, rec.Code, rec.Body.String())
		}
	}
}

// Whichever index.html the binary embeds — the committed placeholder or a
// real `vite build` — every asset it links to must also be embedded. The
// placeholder links to none; a real build links to the bundles vite just
// wrote into dist/, which embeds as a unit, so a broken reference here means
// dist/ was hand-edited.
func TestEmbeddedIndexAssetsExist(t *testing.T) {
	index, err := fs.ReadFile(web.Assets, "index.html")
	if err != nil {
		t.Fatal(err)
	}
	refs := regexp.MustCompile(`(?:src|href)="(/assets/[^"]+)"`).FindAllStringSubmatch(string(index), -1)
	for _, ref := range refs {
		name := strings.TrimPrefix(ref[1], "/")
		if _, err := fs.Stat(web.Assets, name); err != nil {
			t.Errorf("index.html references %s but it is not embedded", ref[1])
		}
	}
}

package dashboard

import (
	"context"
	"fmt"
	"path/filepath"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// topologyProvider fetches the declared topologies for the workspace. Each
// entry's Path is the on-disk system directory (the handler normalizes it to
// a root-relative identifier). Per-host failures are returned as messages
// alongside the successes so one broken host cannot hide the rest.
type topologyProvider func(ctx context.Context) (entries []topology.Entry, errs []string)

// hostGraphProvider returns the default provider: it finds every scaffolded
// system host under root and asks each one to print its declared topology.
// Hosts scaffolded before the graph verb existed simply fail, which surfaces as
// an error the UI renders.
//
// The mechanics live in topology.RunGraph, which deploy init shares. What stays
// here is the dashboard's policy: never fail, report per host.
func hostGraphProvider(root string) topologyProvider {
	return func(ctx context.Context) ([]topology.Entry, []string) {
		hosts, _ := template.ListSystemHosts(root)
		var entries []topology.Entry
		var errs []string
		for _, h := range hosts {
			t, err := topology.RunGraph(ctx, h.Path)
			if err != nil {
				errs = append(errs, fmt.Sprintf("%s: %v", displayPath(root, h.Path), err))
				continue
			}
			// The system directory is the workspace directory holding the
			// host: components are scaffolded as its siblings.
			entries = append(entries, topology.Entry{Path: filepath.Dir(h.Path), Topology: *t})
		}
		return entries, errs
	}
}

// displayPath shortens a host directory to its root-relative form for error
// messages, matching the identifier space the rest of the API uses.
func displayPath(root, p string) string {
	if rel, err := filepath.Rel(root, p); err == nil {
		return filepath.ToSlash(rel)
	}
	return filepath.ToSlash(filepath.Clean(p))
}

import { useCallback, useEffect, useState } from 'react'
import { api, type DeployState, type Integration, type IntegrationDetail } from './api'
import { Sidebar } from './components/Sidebar'
import { DetailPanel } from './components/DetailPanel'
import { FlowView } from './components/FlowView'
import { DarkModeIcon, LightModeIcon, SystemThemeIcon } from './icons'

const SIDEBAR_COLLAPSED_KEY = 'intropy.sidebar.collapsed'
const THEME_KEY = 'intropy.theme'

type View = 'catalog' | 'flow'

const VIEWS: { id: View; label: string }[] = [
  { id: 'catalog', label: 'Integration Catalog' },
  { id: 'flow', label: 'Integration Flow' },
]

// Theme preference cycles light → dark → system. "system" follows the OS,
// resolved to a concrete light/dark value that drives both data-theme (CSS)
// and the flow canvas colorMode.
type ThemePref = 'light' | 'dark' | 'system'
const THEME_ORDER: ThemePref[] = ['light', 'dark', 'system']
const THEME_META: Record<ThemePref, { Icon: typeof LightModeIcon; label: string }> = {
  light: { Icon: LightModeIcon, label: 'Light' },
  dark: { Icon: DarkModeIcon, label: 'Dark' },
  system: { Icon: SystemThemeIcon, label: 'System' },
}

function prefersDark(): boolean {
  return window.matchMedia('(prefers-color-scheme: dark)').matches
}

function resolveTheme(pref: ThemePref): 'light' | 'dark' {
  return pref === 'system' ? (prefersDark() ? 'dark' : 'light') : pref
}

export default function App() {
  const [integrations, setIntegrations] = useState<Integration[] | null>(null)
  const [selected, setSelected] = useState<string | null>(null)
  const [detail, setDetail] = useState<IntegrationDetail | null>(null)
  const [deployState, setDeployState] = useState<DeployState | null>(null)
  const [deployLoading, setDeployLoading] = useState(false)
  const [deployRefreshing, setDeployRefreshing] = useState(false)
  const [version, setVersion] = useState<string>('')
  const [error, setError] = useState<string | null>(null)
  const [collapsed, setCollapsed] = useState<boolean>(
    () => localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === 'true',
  )
  const [view, setView] = useState<View>('catalog')
  const [theme, setTheme] = useState<ThemePref>(
    () => (localStorage.getItem(THEME_KEY) as ThemePref | null) ?? 'system',
  )
  const [resolvedTheme, setResolvedTheme] = useState<'light' | 'dark'>(() =>
    resolveTheme(theme),
  )

  useEffect(() => {
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, String(collapsed))
  }, [collapsed])

  // Apply the theme to <html> and track the resolved value. In system mode,
  // also follow live OS changes; explicit modes ignore them.
  useEffect(() => {
    localStorage.setItem(THEME_KEY, theme)
    const apply = () => {
      const resolved = resolveTheme(theme)
      document.documentElement.dataset.theme = resolved
      setResolvedTheme(resolved)
    }
    apply()
    if (theme !== 'system') return
    const mq = window.matchMedia('(prefers-color-scheme: dark)')
    mq.addEventListener('change', apply)
    return () => mq.removeEventListener('change', apply)
  }, [theme])

  const cycleTheme = () =>
    setTheme((t) => THEME_ORDER[(THEME_ORDER.indexOf(t) + 1) % THEME_ORDER.length])

  useEffect(() => {
    api
      .listIntegrations()
      .then(setIntegrations)
      .catch((e: unknown) => setError(errText(e)))
    api
      .health()
      .then((h) => setVersion(h.version))
      .catch(() => {})
  }, [])

  // Auto-select the first integration once the list loads.
  useEffect(() => {
    if (integrations && integrations.length > 0 && !selected) {
      setSelected(integrations[0].path)
    }
  }, [integrations, selected])

  useEffect(() => {
    if (!selected) {
      setDetail(null)
      return
    }
    setDetail(null)
    api
      .getIntegration(selected)
      .then(setDetail)
      .catch((e: unknown) => setError(errText(e)))
  }, [selected])

  // Deployment state loads on its own, because it costs its own thing: reading
  // it refreshes a GitOps checkout over the network, while the detail above is
  // local files. Keeping them apart lets the panel render straight away.
  //
  // A failed lookup is not an error banner: the reason travels inside the state
  // and belongs in the Deployment section, next to the Refresh that retries it.
  useEffect(() => {
    if (!selected) {
      setDeployState(null)
      return
    }
    setDeployState(null)
    setDeployLoading(true)
    let current = true
    api
      .deployState(selected)
      .then((s) => {
        if (current) setDeployState(s)
      })
      .catch((e: unknown) => {
        if (current) setDeployState({ error: errText(e), readAt: new Date().toISOString() })
      })
      .finally(() => {
        if (current) setDeployLoading(false)
      })
    // Selecting another integration while this is in flight must not let the
    // slower answer land on the newer selection.
    return () => {
      current = false
    }
  }, [selected])

  const refreshDeploy = useCallback(() => {
    if (!selected) return
    setDeployRefreshing(true)
    api
      .refreshDeployState(selected)
      .then(setDeployState)
      .catch((e: unknown) =>
        setDeployState({ error: errText(e), readAt: new Date().toISOString() }),
      )
      .finally(() => setDeployRefreshing(false))
  }, [selected])

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden />
          <span className="brand-name">Intropy</span>
          <span className="brand-sub">dashboard</span>
        </div>
        <nav className="nav">
          {VIEWS.map((v) => (
            <button
              key={v.id}
              className={`nav-item${view === v.id ? ' active' : ''}`}
              onClick={() => setView(v.id)}
              aria-current={view === v.id ? 'page' : undefined}
            >
              {v.label}
            </button>
          ))}
        </nav>
        <div className="topbar-end">
          {version && <span className="version">{version}</span>}
          <ThemeToggle theme={theme} onCycle={cycleTheme} />
        </div>
      </header>

      <div className="layout">
        {view === 'catalog' && (
          <Sidebar
            integrations={integrations}
            selected={selected}
            onSelect={setSelected}
            collapsed={collapsed}
            onToggle={() => setCollapsed((c) => !c)}
          />
        )}
        <main className="content">
          {error && <div className="banner error">{error}</div>}
          {view === 'catalog' ? (
            <DetailPanel
              detail={detail}
              hasSelection={!!selected}
              deploy={{
                state: deployState,
                loading: deployLoading,
                refreshing: deployRefreshing,
                onRefresh: refreshDeploy,
              }}
            />
          ) : (
            <FlowView selected={selected} onSelect={setSelected} theme={resolvedTheme} />
          )}
        </main>
      </div>
    </div>
  )
}

// ThemeToggle cycles the theme preference. The current mode's glyph and a
// title communicate both the active choice and that clicking advances it.
function ThemeToggle({ theme, onCycle }: { theme: ThemePref; onCycle: () => void }) {
  const { Icon, label } = THEME_META[theme]
  return (
    <button
      type="button"
      className="theme-toggle"
      onClick={onCycle}
      title={`Theme: ${label} (click to change)`}
      aria-label={`Theme: ${label}. Click to change.`}
    >
      <Icon className="icon" aria-hidden />
    </button>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}

// Types mirror the Go JSON contract served by `intropy dashboard`
// (internal/dashboard). Integration matches template.ScaffoldEntry;
// IntegrationDetail adds the best-effort on-disk enrichment.

/** A dependency another template rendered alongside this integration. */
export interface DependencyRecord {
  template: string
  /** Slash-separated directory relative to the component root. */
  dir: string
}

export interface Integration {
  path: string
  schemaVersion: number
  template: string
  owner: string
  repo: string
  version: string
  /** Which way data crosses the system boundary, declared by the template
   *  (intropy.dev/data-flow label) and recorded in scaffold.json. */
  dataFlow?: 'in' | 'out' | 'both' | 'internal'
  /** Topology block kind the template scaffolds (intropy.dev/block-kind
   *  label), e.g. "extractor" or "loader". */
  blockKind?: string
  /** Support-project role (intropy.dev/template-role label). Projects with a
   *  role (system-host, shared-library) are filtered out of the catalog by
   *  the server; the field only appears on records read elsewhere. */
  role?: string
  /** Sibling projects this integration's template rendered as dependencies. */
  dependsOn?: DependencyRecord[]
  values: Record<string, unknown>
  /** Directory carrying the .intropy record; the integration's display name. */
  name: string
  /** Parent directory of the integration; absent directly under the root. */
  system?: string
  /** Parent directory of the system; absent when the system sits at the root. */
  domain?: string
  /** Root-relative directory of the system ("." when rooted at the workspace).
   *  The unique system key — two directories can declare the same `system`
   *  name — and the join key to a declared Topology's `path`. */
  systemPath?: string
}

export interface FileDoc {
  name: string
  content: string
}

/** A parsed Dapr component. `category` decides where the flow canvas draws it:
 *  `pubsub`/`state` inside the system boundary, `binding` outside — as a
 *  source when `direction` is `input`, a sink otherwise. */
export interface DaprComponent {
  name: string
  type: string
  category: 'pubsub' | 'state' | 'binding' | 'other'
  /** Normalized `direction` metadata from the component spec. Absent when
   *  undeclared — treated as unknown (rendered as a sink), never inferred. */
  direction?: 'input' | 'output' | 'input,output'
  file: string
}

export interface IntegrationDetail extends Integration {
  agents?: FileDoc
  readme?: FileDoc
  components?: DaprComponent[]
  pipelineSteps?: string[]
}

export interface Health {
  status: string
  version: string
}

// Deployment state (internal/deploy). The server obtains each record by running
// the `deploy status` command with a JSON writer and passing its result through
// unchanged, so everything below is that command's own output — including the
// prose in `summary` and `notes`, which must be rendered as served rather than
// re-derived from `environments`.

/** How one overlay pins one image. */
export interface ResultPin {
  image: string
  /** The digest this replaced. Only present on a deployment's own result. */
  previous?: string
  digest: string
  /** The tag the digest was resolved from, or the tag pinned instead of a
   *  digest. Empty when the digest came from a release manifest. */
  tag?: string
}

/** One environment's row of the deployment ladder. */
export interface EnvironmentStatus {
  environment: string
  appName: string
  overlayPath: string
  /** False means there is no readable overlay here; `reason` says why and
   *  everything below is empty. On its own it never means "not deployed". */
  onboarded: boolean
  reason?: string
  /** The version this environment runs. Absent when it was deployed from a
   *  commit rather than a release, in which case `sourceCommit` stands in. */
  release?: string
  sourceCommit?: string
  /** Every image the component declares, in declared order. `digest` is empty
   *  when the overlay pins a tag or nothing — `tag` says which. */
  pins?: ResultPin[]
  /** The GitOps commit that last changed this overlay, and when it landed.
   *  Both absent when the overlay path has no history. */
  revision?: string
  /** RFC 3339. */
  deployedAt?: string
  syncPolicy: 'auto' | 'manual' | string
  /** What ArgoCD reports. Absent when it could not be read — which says
   *  nothing at all about what the overlay pins. */
  syncStatus?: string
  healthStatus?: string
  syncedRevision?: string
  /** A committed overlay change ArgoCD has not applied. For a `manual`
   *  environment that is an unspent gate at rest, not a fault. */
  pending: boolean
}

export interface StatusResult {
  component: string
  domain: string
  system: string
  /** Declared kind. "shared" holds system-level manifests and no image, so its
   *  empty digests are by design rather than evidence of never deploying. */
  kind: 'service' | 'shared' | string
  /** In promotion order: the last entry is the furthest downstream. */
  environments: EnvironmentStatus[]
  /** Every onboarded environment pins the identical digest for every image —
   *  what makes "prod runs the bits staging tested" a fact. */
  consistent: boolean
  /** The command's own sentence about what the environments collectively run.
   *  Render as served: `consistent` is a bool and the interesting cases are
   *  not — "these run different bits" and "there is nothing to compare" are
   *  both false and mean very different things. */
  summary: string
  /** The command's qualifications: an environment that could not be read, one
   *  pinning a tag, one waiting on a sync gate. */
  notes?: string[]
}

/** The /api/deploy/{path} payload: what the deploy status command said about one
 *  integration, or why it could not say anything. */
export interface DeployState {
  status?: StatusResult
  /** The command's message, verbatim — an unconfigured GitOps repository, a
   *  component name matching several, a checkout another deploy is holding.
   *  None of these is a statement about the integration; only `status` is. */
  error?: string
  /** What the command wrote to stderr: which repository it refreshed, and any
   *  environment ArgoCD could not be read for. Provenance, not failure. */
  diagnostics?: string[]
  /** RFC 3339 — when the command ran. */
  readAt: string
}

// Declared system topology (internal/topology). The server obtains each
// record by running the system host's `graph` verb (apiVersion
// topology.intropy.io/v1) and caches the result until an explicit refresh.
// Wiring is inlined on each component — the topics it subscribes to and
// publishes on and the connectors it uses — while the top-level `topics` and
// `connectors` sections are the lookup tables those inline references resolve
// against. There is no fallback: a system whose host cannot produce a record
// appears in `errors` instead of `topologies`.

/** A component's subscription to a pub/sub topic. */
export interface TopicRef {
  pubsub: string
  topic: string
}

/** A component's output onto a pub/sub topic. */
export interface Publication {
  /** Component output port the message leaves through. */
  port?: string
  pubsub: string
  topic: string
}

/** A component's use of an external connector. */
export interface ConnectorUse {
  connector: string
  /** "in" (external → component) or "out" (component → external). */
  direction: 'in' | 'out'
}

export interface TopologyComponent {
  name: string
  /** Block type: extractor, loader, transactionalIntegration, … */
  kind: string
  subscribes?: TopicRef[]
  publishes?: Publication[]
  connectors?: ConnectorUse[]
  /** Contract surfaces — parsed but not yet rendered (shape not finalized). */
  provides?: unknown[]
  consumes?: unknown[]
}

/** A declared pub/sub topic: metadata for a (pubsub, topic) pair components
 *  reference. */
export interface TopologyTopic {
  pubsub: string
  topic: string
  contract?: string
  publishers?: string[]
  subscribers?: string[]
}

export interface TopologyTransport {
  type: string
  supportsInput: boolean
  supportsOutput: boolean
}

/** An external system integration point. */
export interface TopologyConnector {
  name: string
  externalSystem?: string
  transport: TopologyTransport
  directions?: Array<'in' | 'out'>
  usedBy?: string[]
}

/** A message contract in the system's registry, keyed by `name` — the same
 *  fully-qualified type name TopologyTopic.contract references. */
export interface Contract {
  name: string
  /** "event" for pub/sub message contracts. */
  kind?: string
  /** Bare type name — the join key to a scaffold record's values.contract. */
  shortName?: string
  mediaType?: string
  /** Hash of the schema's canonical form; equal fingerprints mean equal
   *  shapes across systems. */
  fingerprint?: string
  /** JSON Schema as the host emitted it, passed through verbatim. */
  schema?: JsonSchema
}

/** The subset of JSON Schema the contract field tree renders. Anything it
 *  does not recognize falls back to a raw type label, never an error. */
export interface JsonSchema {
  type?: string | string[]
  format?: string
  properties?: Record<string, JsonSchema>
  required?: string[]
  items?: JsonSchema
  enum?: unknown[]
  $ref?: string
  $defs?: Record<string, JsonSchema>
}

/** One field or column of an external payload, as its author described it.
 *  `type` is loose by design — documentation, not a validatable schema. */
export interface MessageDocField {
  name: string
  position?: number
  type?: string
  required?: boolean
  notes?: string
}

/** A short inline payload excerpt. The server only serves samples whose
 *  author explicitly asserted the redaction check. */
export interface MessageDocSample {
  inline: string
  redacted?: boolean
}

/** An authored description of the payload a connector carries (the flat file
 *  from an SFTP drop, the ad-hoc CSV export), read from the system's
 *  messages/<connector>.md sidecar. Documentation, not enforcement. */
export interface MessageDoc {
  format?: string
  delimiter?: string
  encoding?: string
  filePattern?: string
  frequency?: string
  contact?: string
  lastReviewed?: string
  fields?: MessageDocField[]
  sample?: MessageDocSample
  /** Free prose from the doc's Markdown body. */
  body?: string
}

export interface Topology {
  /** Root-relative system directory, same identifier space as Integration.path. */
  path: string
  apiVersion: string
  kind?: string
  /** System name (a bare string in v1). */
  system: string
  components?: TopologyComponent[]
  topics?: TopologyTopic[]
  connectors?: TopologyConnector[]
  /** Message contract registry topics reference by contract name. Absent
   *  until the system host's topology library emits it. */
  contracts?: Contract[]
  /** Contract surfaces — parsed but not yet rendered (shape not finalized). */
  apis?: unknown[]
  /** Authored connector payload descriptions, keyed by connector name.
   *  CLI-merged enrichment from messages/<connector>.md — not part of the
   *  host-declared topology, and re-read on every request. */
  messageDocs?: Record<string, MessageDoc>
}

/** The /api/topology payload: every declared topology plus the per-host
 *  failures (a host whose graph verb failed, e.g. because it pre-dates the
 *  verb or does not build). */
export interface TopologyReport {
  topologies: Topology[]
  errors?: string[]
}

async function requestJSON<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, init)
  if (!res.ok) {
    let message = `${res.status} ${res.statusText}`
    try {
      const body = (await res.json()) as { error?: string }
      if (body?.error) message = body.error
    } catch {
      // response had no JSON error body; keep the status line
    }
    throw new Error(message)
  }
  return (await res.json()) as T
}

const getJSON = <T,>(url: string) => requestJSON<T>(url)

export const api = {
  listIntegrations: () => getJSON<Integration[]>('/api/integrations'),
  getIntegration: (path: string) =>
    getJSON<IntegrationDetail>(`/api/integrations/${path}`),
  /** Every integration enriched with pipeline steps + Dapr components for the flow canvas. */
  flow: () => getJSON<IntegrationDetail[]>('/api/flow'),
  /** Every declared system topology, cached from the hosts' graph verbs. */
  topologies: () => getJSON<TopologyReport>('/api/topology'),
  /** Re-run every host's graph verb and return the fresh report. */
  refreshTopologies: () =>
    requestJSON<TopologyReport>('/api/topology/refresh', { method: 'POST' }),
  /** One integration's deployment state, read once and reused by the server. */
  deployState: (path: string) => getJSON<DeployState>(`/api/deploy/${path}`),
  /** Re-run `deploy status` for one integration and return the fresh result —
   *  how you pick up a deploy just made from another terminal. */
  refreshDeployState: (path: string) =>
    requestJSON<DeployState>(`/api/deploy/${path}`, { method: 'POST' }),
  health: () => getJSON<Health>('/api/health'),
}

import type { ComponentType, ReactNode, SVGProps } from 'react'
import type { DeployState, IntegrationDetail } from '../api'
import { Deployment } from './Deployment'
import {
  DescriptionIcon,
  ExtensionIcon,
  RouteIcon,
  TuneIcon,
} from '../icons'

type IconComponent = ComponentType<SVGProps<SVGSVGElement>>


interface Props {
  detail: IntegrationDetail | null
  hasSelection: boolean
  deploy: DeployProps
}

/** Everything the Deployment section needs. It loads separately from the detail
 *  because it costs very differently: detail is local files, this refreshes a
 *  GitOps checkout over the network. */
export interface DeployProps {
  state: DeployState | null
  loading: boolean
  refreshing: boolean
  onRefresh: () => void
}

export function DetailPanel({ detail, hasSelection, deploy }: Props) {
  if (!hasSelection) {
    return <p className="empty">Select an integration to see its details.</p>
  }
  if (!detail) {
    return <p className="empty">Loading…</p>
  }

  const values = Object.entries(detail.values ?? {})

  return (
    <article className="detail">
      <h1 className="detail-title">{title(detail)}</h1>

      <div className="meta-grid">
        <Meta label="Template" value={detail.template || '—'} />
        <Meta label="Version" value={detail.version} />
        <Meta label="Source" value={`${detail.owner}/${detail.repo}`} />
        <Meta label="Path" value={detail.path} />
      </div>

      {/* Above Values on purpose: where an integration runs is more
          operationally interesting than what it was scaffolded with. */}
      <Deployment
        state={deploy.state}
        loading={deploy.loading}
        refreshing={deploy.refreshing}
        onRefresh={deploy.onRefresh}
      />

      <Section title="Values" icon={TuneIcon}>
        {values.length === 0 ? (
          <p className="muted">No scaffold values.</p>
        ) : (
          <table className="kv">
            <tbody>
              {values.map(([k, v]) => (
                <tr key={k}>
                  <th>{k}</th>
                  <td>{String(v)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Section>

      {detail.pipelineSteps && detail.pipelineSteps.length > 0 && (
        <Section title="Pipeline steps" icon={RouteIcon}>
          <ol className="steps">
            {detail.pipelineSteps.map((s) => (
              <li key={s}>{stepName(s)}</li>
            ))}
          </ol>
        </Section>
      )}

      {detail.components && detail.components.length > 0 && (
        <Section title="Dapr components" icon={ExtensionIcon}>
          <ul className="chips">
            {detail.components.map((c) => (
              <li key={c.file} className="chip" title={c.type}>
                {c.name}
                <span className="chip-sub">{c.type || c.category}</span>
              </li>
            ))}
          </ul>
        </Section>
      )}

      {detail.readme && (
        <Section title={detail.readme.name} icon={DescriptionIcon}>
          <pre className="doc">{detail.readme.content}</pre>
        </Section>
      )}
    </article>
  )
}

export function Meta({ label, value }: { label: string; value: string }) {
  return (
    <div className="meta">
      <span className="meta-label">{label}</span>
      <span className="meta-value">{value}</span>
    </div>
  )
}

export function Section({
  title,
  icon: Icon,
  children,
}: {
  title: string
  icon?: IconComponent
  children: ReactNode
}) {
  return (
    <section className="section">
      <h2 className="section-title">
        {Icon && <Icon className="icon" aria-hidden />}
        {title}
      </h2>
      {children}
    </section>
  )
}

// title matches the sidebar: the integration is named after its folder,
// prefixed with the domain and system folders when they exist.
function title(detail: IntegrationDetail): string {
  const name = detail.name || detail.path
  return [detail.domain, detail.system, name].filter(Boolean).join(' / ')
}

// stepName turns a source filename like "OrderValidateStep.cs" into a readable
// "Order Validate".
function stepName(file: string): string {
  return file
    .replace(/\.[^.]+$/, '')
    .replace(/Step$/, '')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
}

import type { DeployState, EnvironmentStatus, StatusResult } from '../api'
import { Section } from './DetailPanel'
import { CloudIcon } from '../icons'

interface Props {
  state: DeployState | null
  loading: boolean
  refreshing: boolean
  onRefresh: () => void
}

/** The deployment ladder: what every environment runs, in promotion order.
 *
 *  Everything here comes from `intropy deploy status`, and the sentences it
 *  computed are rendered as served. Nothing is inferred: an environment with no
 *  readable overlay says why, and a lookup that failed says so as a statement
 *  about the lookup rather than about the integration. */
export function Deployment({ state, loading, refreshing, onRefresh }: Props) {
  if (loading && !state) {
    return (
      <Section title="Deployment" icon={CloudIcon}>
        <p className="muted">Reading deployment state…</p>
      </Section>
    )
  }
  if (!state) return null

  return (
    <Section title="Deployment" icon={CloudIcon}>
      {state.error ? (
        // The command's own message, unedited. It already names every way to
        // resolve the problem, and none of these is evidence about whether the
        // integration is deployed.
        <p className="deploy-error">{state.error}</p>
      ) : state.status ? (
        <Ladder status={state.status} />
      ) : (
        <p className="muted">No deployment state.</p>
      )}
      <Provenance state={state} refreshing={refreshing} onRefresh={onRefresh} />
    </Section>
  )
}

function Ladder({ status }: { status: StatusResult }) {
  const rows = status.environments ?? []
  // ArgoCD is the only source for these two, and an empty column would read as
  // unhealthy. When none of it was read, say so once instead.
  const argocdRead = rows.some((e) => e.syncStatus || e.healthStatus)

  return (
    <>
      <p className={`deploy-verdict${status.consistent ? ' agrees' : ''}`}>{status.summary}</p>

      {rows.length === 0 ? (
        <p className="muted">This component declares no environments.</p>
      ) : (
        <table className="deploy-table">
          <thead>
            <tr>
              <th>Environment</th>
              <th>Release</th>
              <th>Image</th>
              <th>Age</th>
              {argocdRead && (
                <>
                  <th>Sync</th>
                  <th>Health</th>
                </>
              )}
            </tr>
          </thead>
          <tbody>
            {rows.map((env) => (
              <Row key={env.environment} env={env} argocdRead={argocdRead} />
            ))}
          </tbody>
        </table>
      )}

      {!argocdRead && rows.length > 0 && (
        <p className="muted deploy-aside">
          ArgoCD was not read, so sync and health are unknown — this says nothing
          about what the overlays pin.
        </p>
      )}

      {status.notes?.length ? (
        <ul className="deploy-notes">
          {status.notes.map((note) => (
            <li key={note}>{note}</li>
          ))}
        </ul>
      ) : null}
    </>
  )
}

function Row({ env, argocdRead }: { env: EnvironmentStatus; argocdRead: boolean }) {
  const span = argocdRead ? 5 : 3

  return (
    <tr className={env.onboarded ? undefined : 'not-onboarded'}>
      <th>
        {env.environment}
        {env.syncPolicy === 'manual' && <span className="deploy-tag">manual</span>}
        {/* For a manual environment this is an unspent gate at rest, not a
            fault, so it is never styled as an error. */}
        {env.pending && <span className="deploy-tag waiting">waiting</span>}
      </th>
      {env.onboarded ? (
        <>
          <td>{releaseCell(env)}</td>
          <td>
            <Pins env={env} />
          </td>
          <td>{ageCell(env)}</td>
          {argocdRead && (
            <>
              <td>{env.syncStatus || NONE}</td>
              <td>{env.healthStatus || NONE}</td>
            </>
          )}
        </>
      ) : (
        // Never omit the row: an environment the component declares but that
        // cannot be read is the fact an operator most needs to see.
        <td className="muted" colSpan={span}>
          {env.reason || 'no readable overlay here'}
        </td>
      )}
    </tr>
  )
}

/** Every declared image, not just the first. The terminal shows one because a
 *  table row has no space for more and has to apologise for it in a note; this
 *  has the room. */
function Pins({ env }: { env: EnvironmentStatus }) {
  const pins = env.pins ?? []
  if (pins.length === 0) return <>{NONE}</>

  return (
    <ul className="deploy-pins">
      {pins.map((pin) => (
        <li key={pin.image}>
          <span className="deploy-image">{shortImage(pin.image)}</span>
          {pin.digest ? (
            <span title={pin.digest}>{shortDigest(pin.digest)}</span>
          ) : pin.tag ? (
            // A tag can change what runs without a deployment, which is the
            // whole reason deploy pins digests.
            <span className="deploy-unpinned" title={`pinned to the tag ${pin.tag}, not a digest`}>
              :{pin.tag}
            </span>
          ) : (
            <span className="muted">{NONE}</span>
          )}
        </li>
      ))}
    </ul>
  )
}

function Provenance({ state, refreshing, onRefresh }: Omit<Props, 'loading'>) {
  return (
    <div className="deploy-foot">
      <div className="deploy-foot-text">
        {state?.readAt && <span className="muted">read {readAge(state.readAt)}</span>}
        {state?.diagnostics?.length ? (
          <ul className="deploy-diagnostics">
            {state.diagnostics.map((d) => (
              <li key={d}>{d}</li>
            ))}
          </ul>
        ) : null}
      </div>
      <button
        type="button"
        className="flow-refresh"
        onClick={onRefresh}
        disabled={refreshing}
        title="Re-run deploy status for this integration"
      >
        {refreshing ? 'Refreshing…' : 'Refresh'}
      </button>
    </div>
  )
}

/** What the terminal prints in an empty cell. */
const NONE = '—'

/** releaseCell mirrors the command: an environment deployed from a commit has no
 *  release but still has something true to say, and the `@` prefix is what keeps
 *  the commit from being misread as a version. */
function releaseCell(env: EnvironmentStatus): string {
  if (env.release) return env.release
  if (env.sourceCommit) return `@${env.sourceCommit.slice(0, 7)}`
  return NONE
}

function ageCell(env: EnvironmentStatus): string {
  return env.deployedAt ? humanAge(Date.now() - Date.parse(env.deployedAt)) : NONE
}

function readAge(readAt: string): string {
  const ms = Date.now() - Date.parse(readAt)
  return Number.isNaN(ms) ? 'just now' : `${humanAge(ms)} ago`
}

/** humanAge mirrors the command at one unit, truncating rather than rounding:
 *  119 minutes is "1h", never "2h". A deployment reading as older than it is
 *  would be taken for a change someone else already reviewed. */
function humanAge(ms: number): string {
  const minutes = Math.floor(ms / 60_000)
  if (minutes < 1) return '<1m'
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  if (hours < 48) return `${hours}h`
  return `${Math.floor(hours / 24)}d`
}

/** shortDigest mirrors the command character for character, so a digest read
 *  here is the same string deploy and promote print. */
function shortDigest(digest: string): string {
  const prefix = 'sha256:'
  const hex = digest.startsWith(prefix) ? digest.slice(prefix.length) : null
  return hex && hex.length > 12 ? prefix + hex.slice(0, 12) : digest
}

/** shortImage drops the registry host so the column reads as a component name,
 *  keeping the last two path segments — enough to tell two images apart. */
function shortImage(image: string): string {
  const parts = image.split('/')
  return parts.length <= 2 ? image : parts.slice(-2).join('/')
}

// Package dashboard serves the local Intropy integration dashboard: a small
// stdlib net/http server that exposes a read-only JSON API over the
// integrations discovered under a workspace root and serves the embedded SPA
// that renders them.
//
// It starts no integration processes and changes nothing. What it does run is
// two things, both on request rather than at startup: each system host's `graph`
// verb, for the topology the flow view draws, and the deploy status command, for
// what the catalog reports each environment is running. The second one refreshes
// the cached GitOps checkout and reads ArgoCD, so it is the only part of this
// package that touches the network — asked for one integration at a time, and
// reused until an explicit refresh.
//
// Deployment facts are never derived here. The command owns every refusal that
// matters — an unset gitopsRepo, a component name matching several, an
// environment nobody has onboarded — and its answers are passed through
// verbatim, so the dashboard cannot claim something the command line would not.
package dashboard

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"time"
)

// Options configures a dashboard server. The zero value is not usable; Root is
// required and Addr/Port select the listen address.
type Options struct {
	// Root is the workspace directory scanned for integrations.
	Root string
	// Addr is the host/interface to bind, e.g. "127.0.0.1". Empty binds all.
	Addr string
	// Port is the TCP port to bind. 0 asks the OS for a free port.
	Port int
	// OpenBrowser opens the dashboard URL in the default browser on start.
	OpenBrowser bool
	// Version is reported by GET /api/health.
	Version string
	// Stdout and Stderr receive program output and diagnostics; both default
	// to the process streams when nil.
	Stdout io.Writer
	Stderr io.Writer
}

// shutdownTimeout bounds how long in-flight requests have to drain on Ctrl+C.
const shutdownTimeout = 5 * time.Second

// Serve starts the dashboard and blocks until ctx is cancelled (e.g. SIGINT)
// or the server fails. On cancellation it shuts down gracefully and returns
// nil; it returns a non-nil error only for a real startup or runtime failure.
func Serve(ctx context.Context, opts Options) error {
	if opts.Stdout == nil {
		opts.Stdout = os.Stdout
	}
	if opts.Stderr == nil {
		opts.Stderr = os.Stderr
	}
	root := opts.Root
	if root == "" {
		root = "."
	}

	handler, err := newHandler(root, opts.Version, providers{
		topology: hostGraphProvider(root),
		deploy:   statusCommandProvider(opts.Version),
	})
	if err != nil {
		return fmt.Errorf("run: %w", err)
	}

	addr := net.JoinHostPort(opts.Addr, fmt.Sprintf("%d", opts.Port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return fmt.Errorf("run: cannot listen on %s: %w", addr, err)
	}

	url := displayURL(opts.Addr, ln.Addr())
	fmt.Fprintf(opts.Stderr, "Intropy dashboard running at %s\n", url)
	fmt.Fprintln(opts.Stderr, "Press Ctrl+C to stop.")

	if opts.OpenBrowser {
		if err := openBrowser(url); err != nil {
			fmt.Fprintf(opts.Stderr, "warning: could not open browser: %v\n", err)
		}
	}

	srv := &http.Server{Handler: handler}
	errCh := make(chan error, 1)
	go func() {
		err := srv.Serve(ln)
		if err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
			return
		}
		errCh <- nil
	}()

	select {
	case <-ctx.Done():
		fmt.Fprintln(opts.Stderr, "\nShutting down…")
		shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
		defer cancel()
		if err := srv.Shutdown(shutdownCtx); err != nil {
			return fmt.Errorf("run: shutdown: %w", err)
		}
		return nil
	case err := <-errCh:
		if err != nil {
			return fmt.Errorf("run: server error: %w", err)
		}
		return nil
	}
}

// displayURL builds a browser-friendly URL. It uses the actual bound port
// (important when Port was 0) and rewrites wildcard bind hosts to localhost.
func displayURL(host string, addr net.Addr) string {
	port := 0
	if tcp, ok := addr.(*net.TCPAddr); ok {
		port = tcp.Port
	}
	if host == "" || host == "0.0.0.0" || host == "::" {
		host = "localhost"
	}
	return fmt.Sprintf("http://%s", net.JoinHostPort(host, fmt.Sprintf("%d", port)))
}

