package argocd

import (
	"context"
	"crypto/tls"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

// refreshedToken is what an OIDC refresh yields: the new id_token to
// authenticate with, and the rotated refresh token to record for next time.
type refreshedToken struct {
	idToken      string
	refreshToken string
}

// tokenExpired reports whether a JWT's exp claim has passed. The payload is
// decoded without verifying the signature: the decision here is only whether
// to attempt a refresh, and the server remains the authority on validity.
// A token that cannot be decoded is treated as not expired, so a non-JWT
// credential (an ArgoCD account API key, an opaque token) never triggers one.
func tokenExpired(token string) bool {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return false
	}
	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return false
	}
	var claims struct {
		Exp int64 `json:"exp"`
	}
	if err := json.Unmarshal(payload, &claims); err != nil || claims.Exp == 0 {
		return false
	}
	// A small margin so a token does not expire between the check and the
	// request it was checked for.
	return time.Now().Add(30 * time.Second).After(time.Unix(claims.Exp, 0))
}

// serverSettings is the subset of GET /api/v1/settings the refresh needs:
// where the OIDC issuer lives and which public client the CLI authenticates
// as. The client is public (no secret), so the settings endpoint serves it
// to any authenticated caller.
type serverSettings struct {
	OIDCConfig *struct {
		Issuer      string `json:"issuer"`
		ClientID    string `json:"clientID"`
		CLIClientID string `json:"cliClientID"`
	} `json:"oidcConfig"`
}

// refreshSSOToken redeems an SSO refresh token for a fresh id_token, the same
// exchange the argocd CLI performs when it notices an expired token.
//
// The issuer and client ID come from the server's own settings rather than
// being guessed: ArgoCD installations use anything from Dex to Entra to Okta,
// and the client ID is an installation-specific UUID.
func refreshSSOToken(ctx context.Context, server, refreshToken string, insecure bool) (refreshedToken, error) {
	httpClient := &http.Client{Timeout: 15 * time.Second}
	if insecure {
		httpClient.Transport = &http.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: true}}
	}

	scheme := "https"
	base := server
	if strings.Contains(server, "://") {
		u, err := url.Parse(server)
		if err != nil {
			return refreshedToken{}, fmt.Errorf("parse ArgoCD server %q: %w", server, err)
		}
		scheme, base = u.Scheme, u.Host
	}

	// The settings call authenticates with the refresh token's sibling — the
	// possibly-expired id token is not needed: settings only require *a*
	// valid credential, and the refresh token is presented as a bearer the
	// gateway accepts for this read. If the server rejects it there is no
	// unauthenticated way to learn the client ID, and refreshing is impossible
	// without it.
	settings, err := fetchSettings(ctx, httpClient, scheme, base, refreshToken)
	if err != nil {
		return refreshedToken{}, err
	}
	if settings.OIDCConfig == nil || settings.OIDCConfig.Issuer == "" {
		return refreshedToken{}, fmt.Errorf("%s has no OIDC configuration; run 'argocd relogin'", base)
	}
	clientID := settings.OIDCConfig.CLIClientID
	if clientID == "" {
		clientID = settings.OIDCConfig.ClientID
	}
	if clientID == "" {
		return refreshedToken{}, fmt.Errorf("%s OIDC configuration names no client; run 'argocd relogin'", base)
	}

	tokenURL, err := discoverTokenEndpoint(ctx, httpClient, settings.OIDCConfig.Issuer)
	if err != nil {
		return refreshedToken{}, err
	}
	return redeemRefreshToken(ctx, httpClient, tokenURL, clientID, refreshToken)
}

// fetchSettings reads the server's OIDC issuer and client ID.
func fetchSettings(ctx context.Context, httpClient *http.Client, scheme, base, bearer string) (serverSettings, error) {
	var out serverSettings
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, scheme+"://"+base+"/api/v1/settings", nil)
	if err != nil {
		return out, err
	}
	req.Header.Set("Authorization", "Bearer "+bearer)
	req.Header.Set("Accept", "application/json")
	resp, err := httpClient.Do(req)
	if err != nil {
		return out, fmt.Errorf("read settings from %s: %w", base, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 300 {
		return out, fmt.Errorf("read settings from %s: %s", base, resp.Status)
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return out, fmt.Errorf("decode settings from %s: %w", base, err)
	}
	return out, nil
}

// discoverTokenEndpoint resolves the issuer's token endpoint from its OIDC
// discovery document.
func discoverTokenEndpoint(ctx context.Context, httpClient *http.Client, issuer string) (string, error) {
	wellKnown := strings.TrimSuffix(issuer, "/") + "/.well-known/openid-configuration"
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, wellKnown, nil)
	if err != nil {
		return "", err
	}
	resp, err := httpClient.Do(req)
	if err != nil {
		return "", fmt.Errorf("OIDC discovery for %s: %w", issuer, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 300 {
		return "", fmt.Errorf("OIDC discovery for %s: %s", issuer, resp.Status)
	}
	var doc struct {
		TokenEndpoint string `json:"token_endpoint"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&doc); err != nil || doc.TokenEndpoint == "" {
		return "", fmt.Errorf("OIDC discovery for %s: no token endpoint", issuer)
	}
	return doc.TokenEndpoint, nil
}

// redeemRefreshToken performs the refresh_token grant against the issuer's
// token endpoint. The response's id_token is the credential; a rotated
// refresh_token rides along when the issuer rotates (Entra and Okta do).
func redeemRefreshToken(ctx context.Context, httpClient *http.Client, tokenURL, clientID, refreshToken string) (refreshedToken, error) {
	form := url.Values{
		"grant_type":    {"refresh_token"},
		"client_id":     {clientID},
		"refresh_token": {refreshToken},
		"scope":         {"openid profile email offline_access"},
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, tokenURL, strings.NewReader(form.Encode()))
	if err != nil {
		return refreshedToken{}, err
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("Accept", "application/json")

	resp, err := httpClient.Do(req)
	if err != nil {
		return refreshedToken{}, fmt.Errorf("redeem refresh token: %w", err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return refreshedToken{}, fmt.Errorf("redeem refresh token: %w", err)
	}
	if resp.StatusCode >= 300 {
		// The issuer's own message ("invalid_grant", "token expired") says the
		// refresh token is dead; only an interactive login mints a new one.
		return refreshedToken{}, fmt.Errorf("redeem refresh token: %s: %s — run 'argocd relogin'", resp.Status, strings.TrimSpace(string(body)))
	}

	var out struct {
		IDToken      string `json:"id_token"`
		RefreshToken string `json:"refresh_token"`
	}
	if err := json.Unmarshal(body, &out); err != nil || out.IDToken == "" {
		return refreshedToken{}, fmt.Errorf("redeem refresh token: no id_token in response")
	}
	return refreshedToken{idToken: out.IDToken, refreshToken: out.RefreshToken}, nil
}

// writeRefreshedToken records the refreshed id token and the rotated refresh
// token in the argocd CLI's configuration file, so the next reader — this CLI
// or argocd itself — starts from valid credentials. The file is rewritten with
// its other keys preserved; a write failure is the caller's problem to ignore,
// never a reason to fail an authenticated run.
func writeRefreshedToken(path, server string, tok refreshedToken) error {
	raw, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	// Decode into a node tree rather than CLIConfig: the file is argocd's and
	// carries keys this CLI does not model, all of which must survive.
	var doc yaml.Node
	if err := yaml.Unmarshal(raw, &doc); err != nil {
		return err
	}
	users := mappingValue(&doc, "users")
	if users == nil {
		return fmt.Errorf("%s has no users", path)
	}
	for _, entry := range users.Content {
		if scalarValue(entry, "name") != server {
			continue
		}
		setScalar(entry, "auth-token", tok.idToken)
		if tok.refreshToken != "" {
			setScalar(entry, "refresh-token", tok.refreshToken)
		}
	}
	out, err := yaml.Marshal(&doc)
	if err != nil {
		return err
	}
	return os.WriteFile(path, out, 0o600)
}

// mappingValue returns the sequence node under key in a document node.
func mappingValue(doc *yaml.Node, key string) *yaml.Node {
	if len(doc.Content) == 0 {
		return nil
	}
	root := doc.Content[0]
	for i := 0; i+1 < len(root.Content); i += 2 {
		if root.Content[i].Value == key {
			return root.Content[i+1]
		}
	}
	return nil
}

// scalarValue returns the value of key in a mapping node, or "".
func scalarValue(mapping *yaml.Node, key string) string {
	for i := 0; i+1 < len(mapping.Content); i += 2 {
		if mapping.Content[i].Value == key {
			return mapping.Content[i+1].Value
		}
	}
	return ""
}

// setScalar sets key to value in a mapping node, adding the pair when absent.
func setScalar(mapping *yaml.Node, key, value string) {
	for i := 0; i+1 < len(mapping.Content); i += 2 {
		if mapping.Content[i].Value == key {
			mapping.Content[i+1].Value = value
			return
		}
	}
	mapping.Content = append(mapping.Content,
		&yaml.Node{Kind: yaml.ScalarNode, Value: key},
		&yaml.Node{Kind: yaml.ScalarNode, Value: value},
	)
}

