  const m = /^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/.exec(v)
  if (!m) return undefined
  return [Number(m[1]), Number(m[2]), Number(m[3]), m[4] ?? '']
}

